from scipy.optimize import least_squares
def model(th):
    k,b,A0=th[0],th[1],th[2]
    g=1-np.exp(-k*t**b)
    cols=[np.ones_like(t),P,P**2,P**3,g,g*P,g*P**2,g*P**3,t*P,t*P**2]
    M=np.column_stack(cols)
    return M
def resid(th):
    M=model(th)
    c,_,_,_=np.linalg.lstsq(M,dP_dt,rcond=None)
    return dP_dt-M@c
